// Unpacks the editor bundle that the build embeds in main.js (see scripts/pack-editor.mjs) into
// <plugin folder>/editor/, once per plugin version. A marker file records which payload is there.
import { normalizePath, type DataAdapter } from 'obsidian'
// @ts-expect-error generated by scripts/pack-editor.mjs at build time
import { PAYLOAD, PAYLOAD_ID } from '../build/editor-payload.js'

const MARKER = '.payload-id'

interface Entry {
  path: string
  size: number
}

export async function ensureEditorUnpacked(adapter: DataAdapter, pluginDir: string): Promise<string> {
  const editorDir = normalizePath(`${pluginDir}/editor`)
  const marker = `${editorDir}/${MARKER}`
  if ((await adapter.exists(marker)) && (await adapter.read(marker)).trim() === PAYLOAD_ID) {
    return editorDir
  }

  // A previous version's files, if any, go first, so stale hashed chunks don't pile up.
  if (await adapter.exists(editorDir)) await adapter.rmdir(editorDir, true)

  const raw = await gunzip(base64ToBytes(PAYLOAD as string))
  const view = new DataView(raw.buffer, raw.byteOffset, raw.byteLength)
  const headerLength = view.getUint32(0, true)
  const header = JSON.parse(new TextDecoder().decode(raw.subarray(4, 4 + headerLength))) as Entry[]

  const made = new Set<string>()
  let offset = 4 + headerLength
  for (const entry of header) {
    if (entry.path.includes('..')) throw new Error(`Unexpected path in editor bundle: ${entry.path}`)
    const target = normalizePath(`${editorDir}/${entry.path}`)
    const dir = target.slice(0, target.lastIndexOf('/'))
    if (!made.has(dir)) {
      if (!(await adapter.exists(dir))) await adapter.mkdir(dir)
      made.add(dir)
    }
    const bytes = raw.slice(offset, offset + entry.size)
    await adapter.writeBinary(target, bytes.buffer)
    offset += entry.size
  }
  // Written last: an interrupted unpack leaves no marker and is redone next time.
  await adapter.write(marker, PAYLOAD_ID as string)
  return editorDir
}

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64)
  const out = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
  return out
}

async function gunzip(bytes: Uint8Array): Promise<Uint8Array> {
  const stream = new Blob([bytes as BlobPart]).stream().pipeThrough(new DecompressionStream('gzip'))
  return new Uint8Array(await new Response(stream).arrayBuffer())
}
